package com.afs.guard;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.lang.reflect.*;import org.json.*;
public final class UsabilityOptimizationDeviceTest extends Instrumentation{
 int checks;Activity board;void check(boolean ok,String m){checks++;if(!ok)throw new AssertionError(m);}
 Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 void call(String n,Class<?>[] types,Object... args){runOnMainSync(()->{try{Method m=board.getClass().getDeclaredMethod(n,types);m.setAccessible(true);m.invoke(board,args);}catch(Exception e){throw new RuntimeException(e);}});}
 boolean text(View v,String s){if(v instanceof TextView&&s.contentEquals(((TextView)v).getText()))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(text(((ViewGroup)v).getChildAt(i),s))return true;return false;}
 void inject(long down,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);try{if(!getUiAutomation().injectInputEvent(e,true))throw new AssertionError("input injection failed");}finally{e.recycle();}}
 void restore(SharedPreferences p,Map<String,?> data){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> v:data.entrySet()){Object x=v.getValue();if(x instanceof String)e.putString(v.getKey(),(String)x);else if(x instanceof Boolean)e.putBoolean(v.getKey(),(Boolean)x);else if(x instanceof Long)e.putLong(v.getKey(),(Long)x);else if(x instanceof Integer)e.putInt(v.getKey(),(Integer)x);else if(x instanceof Set)e.putStringSet(v.getKey(),new HashSet<>((Set<String>)x));}e.commit();}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Context c=getTargetContext();SharedPreferences p=c.getSharedPreferences("afs_guard",0);Map<String,?> backup=new HashMap<>(p.getAll());Bundle out=new Bundle();int code=-1;
 try{check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk_gphone"),"emulator only");JSONObject rules=new JSONObject();java.util.Calendar clock=java.util.Calendar.getInstance();int minute=clock.get(java.util.Calendar.HOUR_OF_DAY)*60+clock.get(java.util.Calendar.MINUTE);JSONArray windows=new JSONArray().put(new JSONArray().put((minute+120)%1440).put((minute+180)%1440));for(int i=0;i<200;i++)rules.put("com.afs.virtual.app"+i,new JSONObject().put("d",127).put("freeze",true).put("g",true).put("at",System.currentTimeMillis()).put("w",windows));p.edit().putString("rules",rules.toString()).putString("freeze_slots","[]").commit();
 ActivityMonitor monitor=addMonitor(FreezeBoardActivity.class.getName(),null,false);runOnMainSync(()->c.startActivity(new Intent(c,FreezeBoardActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK)));board=waitForMonitorWithTimeout(monitor,10000);removeMonitor(monitor);check(board!=null,"board opens");Thread.sleep(1200);
 LinearLayout column=(LinearLayout)field(board,"slotsView");ViewGroup card=(ViewGroup)column.getChildAt(0);ViewGroup grid=null;for(int i=0;i<card.getChildCount();i++)if(card.getChildAt(i).getClass().getSimpleName().equals("VirtualApps"))grid=(ViewGroup)card.getChildAt(i);check(grid!=null&&grid.getChildCount()==100,"200 apps keep 100 reusable row shells");final ViewGroup rows=grid;int loaded=0;for(int i=0;i<rows.getChildCount();i++)loaded+=((ViewGroup)rows.getChildAt(i)).getChildCount();check(loaded>0&&loaded<40,"only viewport tiles inflated: "+loaded);View first=rows.getChildAt(0);
 ScrollView scroll=(ScrollView)field(board,"scroll");runOnMainSync(()->scroll.fullScroll(View.FOCUS_DOWN));Thread.sleep(700);check(rows.getChildAt(0)==first&&((ViewGroup)first).getChildCount()==0,"offscreen shells retained and tiles released");runOnMainSync(()->scroll.scrollTo(0,0));Thread.sleep(1500);check(((ViewGroup)first).getChildCount()>0,"scroll restores app tiles");check((Integer)field(rows,"reused")>0,"scroll reuses native tile views rather than rebuilding them");
 call("appDetails",new Class<?>[]{String.class},"com.afs.virtual.app0");Thread.sleep(300);AlertDialog dialog=(AlertDialog)field(board,"applicationPanel");check(dialog!=null&&dialog.isShowing(),"unified panel opens");check(text(dialog.getWindow().getDecorView(),T.s("冻结时段"))&&text(dialog.getWindow().getDecorView(),T.s("使用额度"))&&text(dialog.getWindow().getDecorView(),T.s("断网与修复")),"one panel includes schedule quota and network");call("dismissApplicationPanel",new Class<?>[]{});
 View tile=((ViewGroup)first).getChildAt(0);TextView marker=(TextView)((ViewGroup)((ViewGroup)tile).getChildAt(1)).getChildAt(1);String dragged=(String)marker.getTag();
 call("setLibraryHidden",new Class<?>[]{boolean.class,boolean.class},false,false);Thread.sleep(250);android.graphics.Rect visible=new android.graphics.Rect();runOnMainSync(()->tile.getGlobalVisibleRect(visible));check(!visible.isEmpty(),"native drag source visible");View lib=(View)field(board,"library");int[] xy=new int[2];runOnMainSync(()->lib.getLocationOnScreen(xy));float sx=visible.exactCenterX(),sy=visible.exactCenterY(),tx=xy[0]+lib.getWidth()/2f,ty=xy[1]+lib.getHeight()*.65f;long down=SystemClock.uptimeMillis();inject(down,0,sx,sy);Thread.sleep(ViewConfiguration.getLongPressTimeout()+200);for(int i=0;i<20&&!(Boolean)field(board,"dragging");i++)Thread.sleep(100);if(!(Boolean)field(board,"dragging")){android.graphics.Bitmap shot=getUiAutomation().takeScreenshot();try(java.io.OutputStream file=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),"drag-debug.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,file);}throw new AssertionError("drag source="+visible+" focus="+board.hasWindowFocus()+" locked="+RuleStore.get(c,dragged));}checks++;for(int i=1;i<=8;i++){inject(down,2,sx+(tx-sx)*i/8,sy+(ty-sy)*i/8);Thread.sleep(40);}inject(down,1,tx,ty);for(int i=0;i<30&&!FreezeSlotStore.unassigned(RuleStore.get(c,dragged));i++)Thread.sleep(50);check(FreezeSlotStore.unassigned(RuleStore.get(c,dragged)),"native library drop still clears only schedule binding");
 List<FreezeSlotStore.Slot> slots=FreezeSlotStore.all(c);FreezeSlotStore.Slot target=new FreezeSlotStore.Slot("qa-target",new Rule(127,new int[][]{{(minute+240)%1440,(minute+300)%1440}},true,true));FreezeSlotStore.Slot unchanged=new FreezeSlotStore.Slot("qa-unchanged",new Rule(127,new int[][]{{(minute+360)%1440,(minute+420)%1440}},true,true));slots.add(target);slots.add(unchanged);FreezeSlotStore.save(c,slots);call("rebuild",new Class<?>[]{});Thread.sleep(800);
 Object screenBefore=field(board,"screen"),libraryBefore=field(board,"library");Map<String,View> cards=(Map<String,View>)field(board,"slotViews");View unchangedBefore=cards.get(unchanged.id);
 call("moveApp",new Class<?>[]{String.class,String.class},"com.afs.virtual.app0",target.id);Thread.sleep(1300);
 check(field(board,"screen")==screenBefore&&field(board,"library")==libraryBefore,"moving apps preserves page and catalog views");check(((Map<String,View>)field(board,"slotViews")).get(unchanged.id)==unchangedBefore,"unaffected schedule card is reused");check(FreezeSlotStore.scheduleKey(RuleStore.get(c,"com.afs.virtual.app0")).equals(FreezeSlotStore.scheduleKey(target.rule)),"partial refresh preserves real schedule write");
 out.putString("stream","Usability device: "+checks+" checks passed; initial tiles "+loaded+" / 200\n");code=0;
 }catch(Throwable e){out.putString("stream",android.util.Log.getStackTraceString(e));}finally{if(board!=null)runOnMainSync(board::finishAndRemoveTask);restore(p,backup);finish(code,out);}}
}
